import assert from 'node:assert/strict'
import { createRequire } from 'node:module'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { resolve } from 'node:path'
import { developmentStarter } from './research-benchmark-development.mjs'
import { newVarianceStudy, varianceInventory, varianceMark } from '../../../src/research-variance.mjs'
const { chromium } = createRequire(import.meta.url)(process.env.MC_PLAYWRIGHT_ROOT)
const out = resolve(process.env.BENCHMARK_TEST_OUTPUT || 'prompt-set-browser-proof')
await mkdir(out, { recursive: true })
const browser = await chromium.launch({ headless: true }), errors = []
try {
  const page = await browser.newPage({ viewport: { width: 1440, height: 1100 }, acceptDownloads: true })
  page.on('pageerror', error => errors.push(error.message))
  const f = name => page.locator('[data-bench-' + name + ']'), p = name => page.locator('[data-ps-' + name + ']')
  const idle = () => page.waitForFunction(() => document.querySelector('[data-mc="benchmark"]')?.getAttribute('aria-busy') === 'false')
  const prepared = async () => {
    try { await page.waitForFunction(() => document.querySelector('[data-ps-distribution]')?.textContent.includes('Inclusion probability') && !document.querySelector('[data-ps-prepare]').disabled) }
    catch (error) { console.log(JSON.stringify({ status: await p('status').textContent(), errors })); await page.screenshot({ path: resolve(out, 'failure.png') }); throw error }
  }
  await page.goto(process.env.BENCHMARK_TEST_ORIGIN + '/#/research')
  await page.locator('button[data-research-area="design"]').click()
  assert.equal(await page.locator('button[data-research-area="design"]').textContent(), 'Prompt design')
  const tip = page.getByRole('button', { name: 'Not now', exact: true }); if (await tip.isVisible()) await tip.click()
  await idle()
  await page.locator('button[data-research-area="protocol"]').click()
  await page.locator('[data-projects-btn]').click()
  assert.equal(await page.locator('[data-mc="benchmark"] .bench-start-sections').count(), 0)
  assert.equal(await f('starter').isVisible(), true, 'drafts can be loaded from Protocol through the global Project control')
  await page.screenshot({ path: resolve(out, 'project-dropdown.png') })
  await f('starter').selectOption('lean-bench-snippets-and-compositions'); await f('use-starter').click(); await idle()
  assert.match(await page.locator('[data-projects-btn]').textContent(), /Lean Bench/)
  assert.equal(await page.locator('[data-projects-popover]').isVisible(), false)
  await page.locator('[data-modules-btn]').click()
  const selectedModules = await page.locator('[data-module-toggle]:checked').evaluateAll(nodes => nodes.map(node => node.getAttribute('data-module-toggle')))
  assert.deepEqual(selectedModules, ['data', 'benchmark', 'runboard', 'results', 'library', 'sessions'])
  assert.equal(await page.locator('[data-module-toggle="resource"]').isChecked(), false)
  assert.equal(await page.locator('button[data-research-area="resources"]').isVisible(), false)
  const stored = await page.evaluate(() => JSON.parse(localStorage.getItem('mc.research.modules')))
  assert.ok(stored.disabled.includes('resource')); assert.ok(stored.known.includes('resource'))
  const buttonBox = await page.locator('[data-modules-btn]').boundingBox(), menuBox = await page.locator('[data-modules-popover]').boundingBox()
  assert.ok(Math.abs(buttonBox.x + buttonBox.width - menuBox.x - menuBox.width) < 3 && menuBox.y >= buttonBox.y + buttonBox.height, 'Modules opens directly below its button')
  const projectBox = await page.locator('[data-projects-btn]').boundingBox()
  assert.ok(buttonBox.x - projectBox.x - projectBox.width >= 0 && buttonBox.x - projectBox.x - projectBox.width <= 18, 'Project sits directly beside Modules in the top bar')
  await page.screenshot({ path: resolve(out, 'modules-dropdown.png') })
  await page.locator('[data-module-toggle="resource"]').check(); await page.keyboard.press('Escape')
  await page.locator('button[data-research-area="resources"]').click()
  assert.equal(await page.locator('[data-mc="resource"]').isVisible(), true)
  assert.equal(await page.locator('[data-mc="benchmark"] [data-bench-resource-editor]').count(), 0)
  await page.locator('button[data-research-area="design"]').click()
  await page.locator('[data-bench-tab="corpus"]').click(); await prepared()
  assert.match(await p('counts').textContent(), /available tasks/)
  const leanPool = await p('counts').textContent()
  const spec = developmentStarter(), base = spec.tasks[0]
  spec.tasks = Array.from({ length: 12 }, (_, i) => ({ ...structuredClone(base), id: 'source-' + i, familyId: 'family-' + i % 2, variables: { instruction: 'Case ' + i + ': answer precisely.' }, factors: { group: i < 8 ? 'a' : 'b' } }))
  const source = { kind: 'task', id: spec.tasks[0].id }, inventory = await varianceInventory(spec, null, source)
  const entry = inventory.entries.find(row => row.path === 'root/task'), start = entry.text.indexOf('only ')
  const study = { ...newVarianceStudy('study-1'), name: 'Omit only', source, marks: [varianceMark(inventory, entry.key, start, start + 5)] }
  const file = resolve(out, 'source-draft.json')
  await writeFile(file, JSON.stringify({ spec, editors: { 'data-bench-variance-draft': JSON.stringify({ active: study.id, studies: [study] }) } }))
  await page.locator('[data-projects-btn]').click()
  await f('import').setInputFiles({ name: 'invalid.json', mimeType: 'application/json', buffer: Buffer.from('{') }); await idle()
  assert.equal(await page.locator('[data-projects-popover]').isVisible(), true)
  assert.match(await f('project-status').textContent(), /Draft file/)
  await f('import').setInputFiles(file); await idle(); await page.locator('[data-bench-tab="corpus"]').click(); await prepared()
  assert.equal(await page.locator('[data-projects-popover]').isVisible(), false)
  await page.getByText('Include variants from saved omission studies', { exact: true }).click()
  await p('study').check(); await p('prepare').click(); await prepared()
  assert.match(await p('counts').textContent(), /13 available tasks/); assert.match(await p('counts').textContent(), /1 excluded/)
  await p('method').selectOption('equal'); await p('count').fill('6')
  assert.match(await p('status').textContent(), /requested 3, available 1/); assert.equal(await p('apply').isDisabled(), true)
  await page.locator('[data-ps-dimension="0"]').selectOption('factor:group')
  assert.deepEqual(await p('distribution').locator('tbody tr').evaluateAll(rows => rows.map(row => row.children[3].textContent.trim())), ['3', '3'])
  await p('method').selectOption('weighted'); await p('reset-values').click()
  await page.locator('[data-ps-weight]').nth(0).fill('2'); await page.locator('[data-ps-weight]').nth(1).fill('1')
  assert.deepEqual(await p('distribution').locator('tbody tr').evaluateAll(rows => rows.map(row => row.children[3].textContent.trim())), ['4', '2'])
  await p('rationale').fill('Sample six distinct task/input pairs with a declared 2:1 allocation across groups.')
  await p('inspect').first().click(); await p('read').click(); await page.waitForFunction(() => document.querySelector('[data-ps-wording]')?.textContent.length > 0)
  await p('distribution').evaluate(node => node.scrollIntoView({ block: 'center' }))
  await page.screenshot({ path: resolve(out, 'prompt-distribution-desktop.png') })
  await page.setViewportSize({ width: 850, height: 1100 }); await p('distribution').evaluate(node => node.scrollIntoView({ block: 'start' }))
  assert.ok(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 2))
  await page.screenshot({ path: resolve(out, 'prompt-distribution-narrow.png') })
  await page.setViewportSize({ width: 1440, height: 1100 })
  const ledgerDownload = page.waitForEvent('download'); await p('download').click(); await (await ledgerDownload).saveAs(resolve(out, 'selection-ledger.json'))
  await p('apply').click(); await idle(); await prepared()
  assert.match(await p('counts').textContent(), /6 current tasks/); assert.match(await p('counts').textContent(), /13 available tasks/)
  assert.equal(await p('source').inputValue(), 'retained')
  const draftDownload = page.waitForEvent('download'); await f('draft-export').click()
  const exported = resolve(out, 'selected-draft.json'); await (await draftDownload).saveAs(exported)
  const selected = JSON.parse(await readFile(exported, 'utf8'))
  assert.equal(selected.spec.tasks.length, 6); assert.equal(selected.spec.corpusPlan.pool.tasks.length, 14)
  assert.equal(selected.spec.corpusPlan.selection.kind, 'weighted')
  await f('new-empty').click(); await idle(); await page.locator('[data-bench-tab="corpus"]').click()
  assert.match(await p('counts').textContent(), /0 current tasks/); assert.equal(await p('study').count(), 0)
  await page.locator('[data-projects-btn]').click(); await f('import').setInputFiles(exported); await idle(); await page.locator('[data-bench-tab="corpus"]').click(); await prepared()
  assert.equal(await p('source').inputValue(), 'retained'); assert.equal(await p('method').inputValue(), 'weighted')
  assert.match(await p('counts').textContent(), /13 available tasks/)
  await page.locator('button[data-research-area="resources"]').click()
  await page.locator('[data-mc="resource"] [data-bench-apply-resource-template]').click(); await idle()
  assert.match(await f('resource-status').textContent(), /resource cases generated/)
  assert.equal(await page.locator('[data-mc="resource"]').isVisible(), true)
  assert.deepEqual(errors, [])
  const result = { pass: true, promptDesign: true, sharedProjectPicker: true, invalidDraftPreserved: true, leanPool, leanModulesSaved: selectedModules, resourceOptionalAndSeparate: true, anchoredDropdown: true, omissionPool: true, quotaShortage: true, weightedSelection: [4, 2], generatedTasks: 6, retainedPool: 13, draftRoundTrip: true, errors }
  await writeFile(resolve(out, 'results.json'), JSON.stringify(result, null, 2)); console.log(JSON.stringify(result))
} finally { await browser.close() }
